    @Retry(name = \"member-service\")
    public MemberInfo getMemberDetails(String memberId) {
        return memberServiceClient.getMember(memberId);
    }

    // Fallback method when circuit is open
    private MemberInfo getMemberDetailsFallback(String memberId, Exception e) {
