#### Phase 4: Advanced Configuration (Week 7-8)

**Step 13: Implement Zone-Aware Routing**

```java
// Custom Ribbon configuration for zone-aware routing
@Configuration
public class RibbonConfiguration {
    @Autowired
    private IClientConfig clientConfig;

    @Bean
    public IRule ribbonRule() {
        // Zone-aware routing with fallback to round-robin
        ZoneAvoidanceRule rule = new ZoneAvoidanceRule();
        rule.initWithNiwsConfig(clientConfig);
        return rule;
    }

    @Bean
    public ServerListFilter<Server> ribbonServerListFilter() {
        // Prefer servers in same zone
        return new ZonePreferenceServerListFilter() {
            @Override
            public List<Server> getFilteredListOfServers(List<Server> servers) {
                String currentZone = getCurrentZone();

                // Filter servers in same zone
                List<Server> sameZoneServers = servers.stream()
                    .filter(s -> currentZone.equals(getServerZone(s)))
                    .collect(Collectors.toList());

                // If no servers in same zone, return all servers
                return sameZoneServers.isEmpty() ? servers : sameZoneServers;
            }

            private String getCurrentZone() {
                return System.getenv(\"AVAILABILITY_ZONE\");
            }

            private String getServerZone(Server server) {
                if (server instanceof DiscoveryEnabledServer) {
                    DiscoveryEnabledServer discoveryServer = (DiscoveryEnabledServer) server;
                    return discoveryServer.getInstanceInfo()
                        .getMetadata()
                        .get(\"zone\");
                }
                return null;
            }
        };
    }
}
```

**Step 14: Implement Canary Deployment Routing**

```java
// Custom load balancer rule for canary deployments
public class CanaryAwareRule extends AbstractLoadBalancerRule {
    private Random random = new Random();

    @Override
    public Server choose(Object key) {
        List<Server> servers = getLoadBalancer().getAllServers();

        // Get canary traffic percentage from configuration
        double canaryPercentage = getCanaryPercentage();

        // Randomly decide if this request goes to canary
        if (random.nextDouble() < canaryPercentage) {
            return selectCanaryServer(servers);
        } else {
            return selectStableServer(servers);
        }
    }

    private Server selectCanaryServer(List<Server> servers) {
        List<Server> canaryServers = servers.stream()
            .filter(this::isCanaryServer)
            .collect(Collectors.toList());

        if (canaryServers.isEmpty()) {
            return selectStableServer(servers);  // Fallback
        }

        return canaryServers.get(random.nextInt(canaryServers.size()));
    }

    private boolean isCanaryServer(Server server) {
        if (server instanceof DiscoveryEnabledServer) {
            DiscoveryEnabledServer discoveryServer = (DiscoveryEnabledServer) server;
            String canary = discoveryServer.getInstanceInfo()
                .getMetadata()
                .get(\"canary\");
            return \"true\".equals(canary);
        }
        return false;
    }
}
```

